#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

#[derive(Debug, Clone, Copy)]
pub enum NumpyOperand {
    Scalar(NumpyDType),
    Array(NumpyDType),
}

// ----------------------------------------------------------------
// spec‐level helper
// ----------------------------------------------------------------

#[verus::spec]
pub fn dtype_of(op: &NumpyOperand) -> NumpyDType {
    match *op {
        NumpyOperand::Scalar(dt) | NumpyOperand::Array(dt) => dt,
    }
}

